#!/usr/bin/env python3
"""news-image-01 round 2: write the front-page image to /output/entry.png.

The image is a dense newspaper front page, "THE WORLD TODAY",
Friday 13 November 2026: a lead story (Iran claims a strike on a US
radar in Bahrain), 20 numbered stories from every region and beat, a
"WHERE IT HAPPENED" world map with numbered pins, and an
"ALSO ON 13 NOVEMBER" list. It is embedded below as base64 (one line, 491,633 bytes of JPEG)
and written out byte-identical, deterministically, with no network
access and no model calls. Python 3.13 standard library only.
"""

import base64
import os
import sys

DATA = ""


# The image bytes below are the front page itself, embedded as base64.


def main() -> int:
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    out_path = os.path.join(out_dir, "entry.png")
    raw = base64.b64decode(DATA)
    os.makedirs(out_dir, exist_ok=True)
    with open(out_path, "wb") as fh:
        fh.write(raw)
    return 0


if __name__ == "__main__":
    sys.exit(main())
